// ============================================================================
// Slum Art Picture Rail Gallery Connector
// ============================================================================

const FRAME_STYLES = ["oak", "black", "white", "oak", "black", "white", "black", "oak"];
const MAT_STYLES = [true, true, false, true, true, false, true, true];
const WIRE_DROPS = [0.03, 0.10, -0.02, 0.12, 0.05, -0.03, 0.08, 0.02];

function formatArtworkForRail(art, index, currency) {
  const isUSD = currency === "USD";
  const tag = isUSD ? `$${art.price_usd}` : `₦${(art.price_ngn || 0).toLocaleString()}`;
  
  return {
    id: art.id,
    title: art.title,
    artist: art.artist + (art.age ? ` (${art.age})` : ""),
    year: "2024",
    image: art.image,
    aspect: 0.75,
    frame: FRAME_STYLES[index % FRAME_STYLES.length],
    mat: MAT_STYLES[index % MAT_STYLES.length],
    drop: WIRE_DROPS[index % WIRE_DROPS.length],
    tag: tag,
    price_usd: art.price_usd,
    price_ngn: art.price_ngn,
    details: [
      "Original 1-of-1 Certified Canvas",
      art.medium || "Acrylic on Museum Canvas",
      "Official Certificate of Authenticity",
      art.impact || "Funds 1 Full Term Tuition & Nutritious Meals"
    ],
    link: art.link || "https://paystack.shop/pay/lk0hlrdlun",
    raw: art
  };
}

let _galleryRoot = null;
let _currentCurrency = "NGN";
let _galleryArtworks = [];
let _activeMountEl = null;

function renderGallery(mountEl, artworks, currency) {
  _currentCurrency = currency;
  _galleryArtworks = artworks;
  _activeMountEl = mountEl;

  // Curate top 8 masterpieces so frames hang side-by-side on desktop without crowding
  const featured = artworks.slice(0, 8);
  const items = featured.map((art, idx) => formatArtworkForRail(art, idx, currency));

  function GalleryApp() {
    return M.jsx("div", {
      className: "picture-rail-scope w-full bg-background text-foreground",
      children: M.jsx(J1, {
        items: items,
        eyebrow: "The Curatorial Picture Rail • 100% Direct Scholar Impact",
        heading: "A gallery wall you can rearrange, right on the page.",
        caption: "Brush along the rail to light a print, slide it, lift it to see the back.",
        autoplay: false,
        action: M.jsx("button", {
          type: "button",
          className: "btn-rail-acquire",
          onClick: () => {
            const catalogSec = document.querySelector(".shop-filter-bar, #shopGrid, #art-shop");
            if (catalogSec) catalogSec.scrollIntoView({ behavior: "smooth" });
          },
          children: [
            M.jsx("i", { className: "fas fa-arrow-down mr-2" }),
            "Browse Full Catalog (" + artworks.length + " Originals)"
          ]
        })
      })
    });
  }

  if (!_galleryRoot) {
    _galleryRoot = s1.createRoot(mountEl);
  }
  _galleryRoot.render(M.jsx(a1.StrictMode, { children: M.jsx(GalleryApp, {}) }));
}

window.mountPictureRailGallery = function(container, customArtworks = null) {
  const mountEl = typeof container === "string" ? document.getElementById(container) : container;
  if (!mountEl) {
    console.error("[PictureRail] Container element not found:", container);
    return;
  }

  const currency = (window.localStorage && localStorage.getItem("slum_art_currency")) || (window.currentCurrency || "NGN");

  if (customArtworks && customArtworks.length > 0) {
    renderGallery(mountEl, customArtworks, currency);
  } else if (window.DATA && window.DATA.artworks && window.DATA.artworks.length > 0) {
    renderGallery(mountEl, window.DATA.artworks, currency);
  } else if (window.DATA_ARTWORKS && window.DATA_ARTWORKS.length > 0) {
    renderGallery(mountEl, window.DATA_ARTWORKS, currency);
  } else {
    fetch("data_artworks.json")
      .then(res => res.json())
      .then(data => {
        renderGallery(mountEl, data, currency);
      })
      .catch(err => {
        console.error("[PictureRail] Failed to load artworks data:", err);
      });
  }
};

window.addEventListener("currencyChanged", (e) => {
  const newCurr = e.detail || (localStorage.getItem("slum_art_currency") || "NGN");
  if (_activeMountEl && _galleryArtworks.length > 0) {
    renderGallery(_activeMountEl, _galleryArtworks, newCurr);
  }
});
